            {/* Scanner Line */}
            {debouncedPlace.length > 3 && (
                <div className="absolute top-0 left-0 w-full h-1 bg-green-400/30 shadow-[0_0_15px_rgba(74,222,128,0.5)] z-20 animate-[scan_2s_ease-in-out_infinite]"></div>
