    if (!supabase) return;
    const payload = { name: astro.name, specialty: astro.specialty, rating: astro.rating, reviews: astro.reviews, price_per_min: astro.pricePerMin, image_url: astro.imageUrl, is_online: astro.isOnline };
    if (astro.id && astro.id.length > 10) { await supabase.from('astrologers').update(payload).eq('id', astro.id); }
    else { await supabase.from('astrologers').insert([payload]); }
};

export const deleteAstrologer = async (id: string) => { if (supabase) await supabase.from('astrologers').delete().eq('id', id); };

export const fetchProducts = async (): Promise<Product[]> => {
  if (!supabase) return MOCK_PRODUCTS;
  try {
      const { data, error } = await supabase.from('products').select('*');
      if (error || !data || data.length === 0) return MOCK_PRODUCTS;
      return data.map((p: any) => ({ id: p.id, name: p.name, category: p.category, price: p.price, description: p.description, benefits: p.benefits, imageUrl: p.image_url }));
  } catch (e) { return MOCK_PRODUCTS; }
};

export const createProduct = async (product: Product): Promise<Product | null> => {
  if (!supabase) return product;
  try {
      const payload = { name: product.name, category: product.category, price: product.price, description: product.description, benefits: product.benefits, image_url: product.imageUrl };
      let data, error;
      if (product.id && product.id.length > 10 && !product.id.startsWith('p')) { ({ data, error } = await supabase.from('products').update(payload).eq('id', product.id).select().single()); }
      else { ({ data, error } = await supabase.from('products').insert([payload]).select().single()); }
      if (error) return null;
      return { ...product, id: data.id, name: data.name, imageUrl: data.image_url, category: data.category };
  } catch (e) { return null; }
};

export const deleteProductFromDb = async (id: string): Promise<boolean> => {
    if (!supabase) return true;
    try { const { error } = await supabase.from('products').delete().eq('id', id); return !error; }
    catch (e) { return false; }
};

export const fetchTransactions = async (): Promise<Transaction[]> => {
  if (!supabase) return [];
  try {
      const { data, error } = await supabase.from('transactions').select('*').order('created_at', { ascending: false });
      if (error) return [];
      return data.map((t: any) => ({ id: t.id, userId: t.user_id, userName: t.user_name, amount: t.amount, type: t.type, status: t.status, date: new Date(t.created_at).toISOString().split('T')[0], details: t.details }));
  } catch (e) { return []; }
};

export const saveTransaction = async (tx: Transaction) => {
  if (!supabase) return;
  try { await supabase.from('transactions').insert([{ id: tx.id, user_id: tx.userId, user_name: tx.userName, amount: tx.amount, type: tx.type, details: tx.details, status: tx.status, created_at: new Date().toISOString() }]); }
  catch (e) {}
};

export const fetchProfiles = async () => {
    if (!supabase) return [];
    const { data } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
    return data || [];
};

export const updateProfile = async (id: string, updates: any) => {
    if (supabase) await supabase.from('profiles').update(updates).eq('id', id);
};

export const fetchUserProfile = async (contact: string | string[]): Promise<{ profile: any | null, chatHistory: Message[] }> => {
  if (!supabase) return { profile: null, chatHistory: [] };
  try {
      let query = supabase.from('profiles').select('*');
      if (Array.isArray(contact)) { query = query.in('contact', contact); }
      else { query = query.eq('contact', contact); }
      const { data, error } = await query.limit(1).maybeSingle();
      if (error || !data) return { profile: null, chatHistory: [] };
      let messages: Message[] = [];
      if (data.chat_history) {
          const decrypted = decryptAndDecompress(data.chat_history);
          if (decrypted) { messages = decrypted.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })); }
      }
      return {
        profile: { id: data.id, contact: data.contact, name: data.name, gender: data.gender, birthDate: data.birth_date, birthTime: data.birth_time, birthPlace: data.birth_place, isPremium: data.is_premium, dailyQuestionsLeft: data.daily_questions_left, subscriptionExpiry: data.subscription_expiry ? new Date(data.subscription_expiry) : undefined },
        chatHistory: messages
      };
  } catch (e) { return { profile: null, chatHistory: [] }; }
};

export const generateUniqueUsername = async (fullName: string): Promise<string> => {
    if (!supabase) return fullName.split(' ')[0];
    const firstName = fullName.trim().split(' ')[0];
    try {
        const { data } = await supabase.from('profiles').select('name').ilike('name', `%${firstName}`);
        if (!data || data.length === 0) return firstName;
        const matches = data.filter(p => p.name.toLowerCase() === firstName.toLowerCase() || p.name.toLowerCase().endsWith(` ${firstName.toLowerCase()}`));
        if (matches.length === 0) return firstName;
        return `+${matches.length.toString().padStart(2, '0')} ${firstName}`;
    } catch (e) { return firstName; }
};

export const saveUserProfile = async (user: UserState, messages?: Message[]) => {
  if (!supabase || !user.contact) return; 
  try {
      const payload: any = { contact: user.contact, name: user.name || '', gender: user.gender || '', birth_date: user.birthDate || '', birth_time: user.birthTime || '', birth_place: user.birthPlace || '', is_premium: !!user.isPremium, daily_questions_left: typeof user.dailyQuestionsLeft === 'number' ? user.dailyQuestionsLeft : 0, subscription_expiry: user.subscriptionExpiry ? user.subscriptionExpiry.toISOString() : null };
      if (messages && messages.length > 0) payload.chat_history = compressAndEncrypt(messages);
      await supabase.from('profiles').upsert(payload, { onConflict: 'contact' });
  } catch (e) {}
};

export const fetchCommunicationLogs = async (): Promise<CommunicationLog[]> => {
    if (!supabase) return [];
    try {
        const { data, error } = await supabase.from('communications').select('*').order('timestamp', { ascending: false });
        if (error || !data) return [];
        return data.map((log: any) => ({ id: log.id, type: log.type, recipient: log.recipient, direction: log.direction, status: log.status, timestamp: log.timestamp, details: log.details }));
    } catch (e) { return []; }
};

