import React, { useState, useEffect } from 'react';
import { sendAuthOtp, verifyAuthOtp, fetchUserProfile } from '../../services/dbService';

export interface OnboardingData {
  contact: string;
  name: string;
  gender: string;
  date: string;
  time: string;
  place: string;
}

interface UserOnboardingProps {
  onSubmit: (data: OnboardingData, wantsPremium: boolean) => void;
  onGuruLogin?: () => void;
}

const COUNTRY_CODES = [
    { code: '+91', country: 'IN', label: 'India (+91)' },
    { code: '+1', country: 'US', label: 'USA/Canada (+1)' },
    { code: '+44', country: 'UK', label: 'UK (+44)' },
    { code: '+61', country: 'AU', label: 'Australia (+61)' },
    { code: '+971', country: 'AE', label: 'UAE (+971)' },
];

const UserOnboarding: React.FC<UserOnboardingProps> = ({ onSubmit, onGuruLogin }) => {
  const [step, setStep] = useState(1);
  const [contactInput, setContactInput] = useState('');
  const [countryCode, setCountryCode] = useState('+91');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [isOtpVerified, setIsOtpVerified] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [timer, setTimer] = useState(0);
  const [debouncedPlace, setDebouncedPlace] = useState('');

  const [formData, setFormData] = useState<OnboardingData>({
    contact: '',
    name: '',
    gender: '',
    date: '',
    time: '',
    place: ''
  });

  const isEmailDetected = /[a-zA-Z@]/.test(contactInput);

  useEffect(() => {
    let interval: any;
    if (timer > 0) interval = setInterval(() => setTimer(prev => prev - 1), 1000);
    return () => clearInterval(interval);
  }, [timer]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedPlace(formData.place), 1000);
    return () => clearTimeout(handler);
  }, [formData.place]);

  useEffect(() => {
      setErrorMsg('');
      if (isEmailDetected) setFormData(prev => ({ ...prev, contact: contactInput }));
      else setFormData(prev => ({ ...prev, contact: `${countryCode}${contactInput.trim()}` }));
  }, [contactInput, countryCode, isEmailDetected]);

  const handleNext = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setStep(prev => prev + 1);
  };

  const handleSendOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');
      const contact = isEmailDetected ? contactInput : `${countryCode}${contactInput.trim()}`;
      try {
        const { profile } = await fetchUserProfile(contact);
        if (profile) {
            setIsLoading(false);
            setErrorMsg("Already registered. Please login instead.");
            return;
        }
        const result = await sendAuthOtp(contact);
        setIsLoading(false);
        if (result.success) { setOtpSent(true); setTimer(60); } 
        else { setErrorMsg(result.message || "Failed to send code."); }
      } catch (err) { setIsLoading(false); }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');
      const contact = isEmailDetected ? contactInput : `${countryCode}${contactInput.trim()}`;
      const result = await verifyAuthOtp(contact, otp);
      setIsLoading(false);
      if (result.success) {
          setIsOtpVerified(true);
          handleNext(); // Proceed directly to details
      } else { setErrorMsg(result.message || "Invalid Code."); }
  };

  const renderStep1 = () => (
    <div className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
