             <h3 className="text-xl font-serif text-white">Let's verify your identity</h3>
             <p className="text-mystic-400 text-sm">One-click verification to secure your destiny.</p>
        </div>
        <form onSubmit={otpSent ? handleVerifyOtp : handleSendOtp} className="space-y-4">
            <div className="flex gap-2">
                {!isEmailDetected && !otpSent && (
                    <select value={countryCode} onChange={(e) => setCountryCode(e.target.value)} className="h-full bg-mystic-900/50 border border-mystic-700 rounded-xl px-2 text-white focus:outline-none focus:border-gold-500 text-sm">
                        {COUNTRY_CODES.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
                    </select>
                )}
                <input type="text" value={contactInput} onChange={e => setContactInput(e.target.value)} disabled={otpSent || isLoading} className="flex-1 bg-mystic-900/50 border border-mystic-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-gold-500" placeholder="Mobile number or email" autoFocus={!otpSent} />
            </div>
            {otpSent && (
                <div className="mt-4 bg-mystic-800/50 p-4 rounded-xl border border-gold-500/30">
                    <input type="text" value={otp} onChange={(e) => setOtp(e.target.value.trim())} placeholder="• • • • • •" maxLength={6} className="w-full bg-mystic-900 border-2 border-mystic-700 focus:border-gold-500 rounded-lg py-3 text-center text-2xl tracking-[0.5em] text-white outline-none font-mono" autoFocus />
                    <button type="button" onClick={handleSendOtp} disabled={timer > 0} className="text-[10px] underline text-mystic-400 mt-2 block mx-auto">{timer > 0 ? `Resend in ${timer}s` : 'Resend Code'}</button>
                </div>
            )}
            {errorMsg && <p className="text-red-400 text-xs text-center font-bold">{errorMsg}</p>}
            <button type="submit" disabled={isLoading} className="w-full bg-gold-500 hover:bg-gold-400 text-mystic-900 font-bold py-4 rounded-xl shadow-lg transition-all flex justify-center">
                {isLoading ? <div className="w-5 h-5 border-2 border-mystic-900 border-t-transparent rounded-full animate-spin"></div> : (otpSent ? 'Verify & Continue' : 'Send Code')}
            </button>
        </form>
    </div>
  );

  const renderStep2 = () => (
    <form onSubmit={handleNext} className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
        <div className="text-center mb-6"><div className="w-12 h-12 bg-mystic-700/50 rounded-full flex items-center justify-center mx-auto mb-3 text-2xl">👤</div><h3 className="text-xl font-serif text-white">Who are you?</h3></div>
        <div className="space-y-4">
            <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-mystic-900/50 border border-mystic-700 rounded-xl px-4 py-4 text-white" placeholder="Full name" autoFocus />
            <div className="grid grid-cols-3 gap-3">
                {['Male', 'Female', 'Other'].map(g => <button type="button" key={g} onClick={() => setFormData({...formData, gender: g})} className={`py-3 rounded-xl border font-bold text-sm ${formData.gender === g ? 'bg-gold-500/20 border-gold-500 text-gold-400' : 'bg-mystic-900/30 border-mystic-700 text-mystic-400'}`}>{g}</button>)}
            </div>
        </div>
        <button type="submit" disabled={!formData.name || !formData.gender} className="w-full bg-gold-500 text-mystic-900 font-bold py-4 rounded-xl">Next Step →</button>
    </form>
  );

  const renderStep3 = () => (
    <form onSubmit={handleNext} className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
        <div className="text-center mb-6"><div className="w-12 h-12 bg-mystic-700/50 rounded-full flex items-center justify-center mx-auto mb-3 text-2xl">🕒</div><h3 className="text-xl font-serif text-white">Moment of Arrival</h3></div>
        <div className="grid grid-cols-1 gap-5">
            <input type="date" required value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full bg-mystic-900/50 border border-mystic-700 rounded-xl px-4 py-4 text-white [color-scheme:dark]" />
            <input type="time" required value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} className="w-full bg-mystic-900/50 border border-mystic-700 rounded-xl px-4 py-4 text-white [color-scheme:dark]" />
        </div>
        <button type="submit" disabled={!formData.date || !formData.time} className="w-full bg-gold-500 text-mystic-900 font-bold py-4 rounded-xl">Next Step →</button>
    </form>
  );

  const renderStep4 = () => (
    <form onSubmit={handleNext} className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
        <div className="text-center mb-6"><div className="w-12 h-12 bg-mystic-700/50 rounded-full flex items-center justify-center mx-auto mb-3 text-2xl">🌍</div><h3 className="text-xl font-serif text-white">Place of Origin</h3></div>
        <input type="text" required value={formData.place} onChange={e => setFormData({...formData, place: e.target.value})} className="w-full bg-mystic-900/50 border border-mystic-700 rounded-xl px-4 py-4 text-white font-bold" placeholder="City, State, Country" autoFocus />
        <button type="submit" disabled={!formData.place} className="w-full bg-gold-500 text-mystic-900 font-bold py-4 rounded-xl">Unlock Destiny →</button>
    </form>
  );

  const renderStep5 = () => (
    <div className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
        <div className="text-center mb-6"><div className="w-16 h-16 bg-gradient-to-tr from-gold-400 to-yellow-600 rounded-full flex items-center justify-center mx-auto mb-4 text-3xl">🔓</div><h3 className="text-2xl font-serif text-white mb-2">Final Step</h3></div>
        <div className="bg-gradient-to-br from-mystic-800 to-mystic-900 border border-gold-500/30 rounded-2xl p-6 relative overflow-hidden group">
            <h4 className="text-lg font-bold text-white">Premium Access</h4>
            <p className="text-gold-400 font-bold text-xl mb-4">₹299 <span className="text-xs font-normal text-mystic-400">/ month</span></p>
            <ul className="space-y-2 mb-6 text-sm text-mystic-300">
                <li><span className="text-green-400">✓</span> 10 Detailed Questions Daily</li>
                <li><span className="text-green-400">✓</span> Full Vastu Blueprints</li>
            </ul>
            <button onClick={() => onSubmit(formData, true)} className="w-full bg-gold-500 text-mystic-900 font-bold py-3.5 rounded-xl">Unlock Premium Now</button>
        </div>
        <div className="text-center"><button onClick={() => onSubmit(formData, false)} className="text-sm text-mystic-400 underline">Continue Free (1 Question)</button></div>
    </div>
  );

  return (
    <div className="flex flex-col items-center justify-center flex-1 w-full p-4">
      <div className="bg-mystic-800/60 backdrop-blur-xl border border-white/10 p-8 rounded-3xl w-full max-w-md shadow-2xl relative">
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-mystic-900 rounded-t-3xl overflow-hidden"><div className="h-full bg-gold-500 transition-all duration-500" style={{ width: `${(step / 5) * 100}%` }}></div></div>
        <div className="mt-4">{step === 1 && renderStep1()}{step === 2 && renderStep2()}{step === 3 && renderStep3()}{step === 4 && renderStep4()}{step === 5 && renderStep5()}</div>
      </div>
    </div>
  );
};

