import { supabase } from './supabaseClient';
import { Product, Transaction, UserState, Message, Astrologer, CommunicationLog } from '../types';
import { MOCK_PRODUCTS, MOCK_ASTROLOGERS } from '../constants';
import { compressAndEncrypt, decryptAndDecompress } from './securityService';

// --- HELPERS ---
export const generateReferenceId = (type: 'Product' | 'Subscription' | 'Dakshina' | 'Consultation' | 'Log', subtype?: string) => {
    const random = Math.floor(1000 + Math.random() * 9000);
    let prefix = 'GEN';
    switch(type) {
        case 'Product': prefix = 'STR'; break;
        case 'Consultation': prefix = 'CNS'; break;
        case 'Subscription': prefix = 'SUB'; break;
        case 'Dakshina': prefix = 'TIP'; break;
        case 'Log': prefix = 'LOG'; break;
    }
    if (subtype && type === 'Subscription') {
        let tierCode = 'GEN';
        const lowerSub = subtype.toLowerCase();
        if (lowerSub.includes('monthly')) tierCode = 'MTH';
        else if (lowerSub.includes('yearly')) tierCode = 'YR';
        return `${prefix}-${tierCode}-${random}`;
    }
    return `${prefix}-${random}`;
};

// --- LOGGING ---
export const logCommunication = async (
    type: CommunicationLog['type'],
    recipient: string,
    direction: CommunicationLog['direction'],
    status: CommunicationLog['status'],
    details?: string
) => {
    const logId = generateReferenceId('Log');
    if (supabase) {
        try {
            await supabase.from('communications').insert([{
                id: logId,
                type,
                recipient,
                direction,
                status,
                details,
                timestamp: new Date().toISOString()
            }]);
        } catch (e) {}
    }
};

// --- RATE LIMITING LOGIC ---
const checkOtpRateLimit = async (contact: string): Promise<{ allowed: boolean; message?: string }> => {
    if (!supabase) return { allowed: true };
    const oneHourAgo = new Date(Date.now() - 3600000).toISOString();

    // 1. Check user-specific limit (1 per hour)
    const { count: userCount } = await supabase
        .from('communications')
        .select('*', { count: 'exact', head: true })
        .eq('recipient', contact)
        .eq('status', 'sent')
        .in('type', ['email', 'sms'])
        .gte('timestamp', oneHourAgo);

    if (userCount !== null && userCount >= 1) {
        return { allowed: false, message: "Limit reached: 1 OTP per hour for this contact." };
    }

    // 2. Check global limit (15 per hour)
    const { count: globalCount } = await supabase
        .from('communications')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'sent')
        .in('type', ['email', 'sms'])
        .gte('timestamp', oneHourAgo);

    if (globalCount !== null && globalCount >= 15) {
        return { allowed: false, message: "System busy: Global hourly OTP limit reached. Please try later." };
    }

    return { allowed: true };
};

// --- AUTHENTICATION (OTP-ONLY) ---
export const sendAuthOtp = async (contact: string): Promise<{ success: boolean; message?: string; isRateLimit?: boolean }> => {
    if (!supabase) return { success: false, message: "System not initialized" };

    // Apply strict custom rate limits
    const limitCheck = await checkOtpRateLimit(contact);
    if (!limitCheck.allowed) {
        return { success: false, message: limitCheck.message, isRateLimit: true };
    }

    const isEmail = /[a-zA-Z@]/.test(contact);
    try {
        let error;
        if (isEmail) {
            const res = await supabase.auth.signInWithOtp({
                email: contact,
                options: { shouldCreateUser: true }
            });
            error = res.error;
        } else {
            const phone = contact.replace(/[\s-]/g, '');
            const res = await supabase.auth.signInWithOtp({
                phone: phone,
                options: { shouldCreateUser: true }
            });
            error = res.error;
        }

        if (error) {
            await logCommunication(isEmail ? 'email' : 'sms', contact, 'outbound', 'failed', error.message);
            return { success: false, message: error.message };
        }

        await logCommunication(isEmail ? 'email' : 'sms', contact, 'outbound', 'sent', 'OTP Sent Successfully');
        return { success: true };
    } catch (e: any) {
        return { success: false, message: e.message };
    }
};

export const verifyAuthOtp = async (contact: string, token: string): Promise<{ success: boolean; message?: string }> => {
    if (!supabase) return { success: false, message: "System not initialized" };
    const isEmail = /[a-zA-Z@]/.test(contact);
    try {
        let error, data;
        if (isEmail) {
            ({ data, error } = await supabase.auth.verifyOtp({ email: contact, token, type: 'email' }));
        } else {
            const phone = contact.replace(/[\s-]/g, '');
            ({ data, error } = await supabase.auth.verifyOtp({ phone, token, type: 'sms' }));
        }

        if (error) return { success: false, message: error.message };

        if (data.session) {
            await logCommunication(isEmail ? 'email' : 'sms', contact, 'inbound', 'completed', 'OTP Verified');
            return { success: true };
        }
        return { success: false, message: "Invalid code." };
    } catch (e: any) {
        return { success: false, message: "Verification failed." };
    }
};

// --- DATA FETCHING ---
export const seedDatabase = async () => {
    if (!supabase) return;
    try {
        const { count: prodCount } = await supabase.from('products').select('*', { count: 'exact', head: true });
        if (prodCount === 0) {
            await supabase.from('products').insert(MOCK_PRODUCTS.map(p => ({ name: p.name, category: p.category, price: p.price, description: p.description, benefits: p.benefits, image_url: p.imageUrl })));
        }
        const { count: astroCount } = await supabase.from('astrologers').select('*', { count: 'exact', head: true });
        if (astroCount === 0) {
            await supabase.from('astrologers').insert(MOCK_ASTROLOGERS.map(a => ({ name: a.name, specialty: a.specialty, rating: a.rating, reviews: a.reviews, price_per_min: a.pricePerMin, image_url: a.imageUrl, is_online: a.isOnline })));
        }
    } catch (e) {}
};

export const subscribeToTable = (table: string, callback: (payload: any) => void) => {
    if (!supabase) return null;
    return supabase.channel(`public:${table}`).on('postgres_changes', { event: '*', schema: 'public', table }, callback).subscribe();
};

export const fetchAstrologers = async (): Promise<Astrologer[]> => {
    if (!supabase) return MOCK_ASTROLOGERS;
    try {
        const { data, error } = await supabase.from('astrologers').select('*').order('is_online', { ascending: false });
        if (error || !data) return MOCK_ASTROLOGERS;
        return data.map((a: any) => ({ id: a.id, name: a.name, specialty: a.specialty, rating: a.rating, reviews: a.reviews, pricePerMin: a.price_per_min, imageUrl: a.image_url, isOnline: a.is_online }));
    } catch (e) { return MOCK_ASTROLOGERS; }
};

export const saveAstrologer = async (astro: Partial<Astrologer>) => {
    if (!supabase) return;
    const payload = { name: astro.name, specialty: astro.specialty, rating: astro.rating, reviews: astro.reviews, price_per_min: astro.pricePerMin, image_url: astro.imageUrl, is_online: astro.isOnline };
    if (astro.id && astro.id.length > 10) { await supabase.from('astrologers').update(payload).eq('id', astro.id); }
    else { await supabase.from('astrologers').insert([payload]); }
};

export const deleteAstrologer = async (id: string) => { if (supabase) await supabase.from('astrologers').delete().eq('id', id); };

export const fetchProducts = async (): Promise<Product[]> => {
  if (!supabase) return MOCK_PRODUCTS;
  try {
      const { data, error } = await supabase.from('products').select('*');
      if (error || !data || data.length === 0) return MOCK_PRODUCTS;
      return data.map((p: any) => ({ id: p.id, name: p.name, category: p.category, price: p.price, description: p.description, benefits: p.benefits, imageUrl: p.image_url }));
  } catch (e) { return MOCK_PRODUCTS; }
};

export const createProduct = async (product: Product): Promise<Product | null> => {
  if (!supabase) return product;
  try {
      const payload = { name: product.name, category: product.category, price: product.price, description: product.description, benefits: product.benefits, image_url: product.imageUrl };
      let data, error;
      if (product.id && product.id.length > 10 && !product.id.startsWith('p')) { ({ data, error } = await supabase.from('products').update(payload).eq('id', product.id).select().single()); }
      else { ({ data, error } = await supabase.from('products').insert([payload]).select().single()); }
      if (error) return null;
      return { ...product, id: data.id, name: data.name, imageUrl: data.image_url, category: data.category };
  } catch (e) { return null; }
};

export const deleteProductFromDb = async (id: string): Promise<boolean> => {
    if (!supabase) return true;
    try { const { error } = await supabase.from('products').delete().eq('id', id); return !error; }
    catch (e) { return false; }
};

export const fetchTransactions = async (): Promise<Transaction[]> => {
  if (!supabase) return [];
  try {
      const { data, error } = await supabase.from('transactions').select('*').order('created_at', { ascending: false });
      if (error) return [];
      return data.map((t: any) => ({ id: t.id, userId: t.user_id, userName: t.user_name, amount: t.amount, type: t.type, status: t.status, date: new Date(t.created_at).toISOString().split('T')[0], details: t.details }));
