};

export const fetchProfiles = async () => {
    if (!supabase) return [];
    const { data } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
    return data || [];
};

export const updateProfile = async (id: string, updates: any) => {
    if (supabase) await supabase.from('profiles').update(updates).eq('id', id);
};

export const fetchUserProfile = async (contact: string | string[]): Promise<{ profile: any | null, chatHistory: Message[] }> => {
  if (!supabase) return { profile: null, chatHistory: [] };
  try {
      let query = supabase.from('profiles').select('*');
      if (Array.isArray(contact)) { query = query.in('contact', contact); }
      else { query = query.eq('contact', contact); }
      const { data, error } = await query.limit(1).maybeSingle();
      if (error || !data) return { profile: null, chatHistory: [] };
      let messages: Message[] = [];
      if (data.chat_history) {
          const decrypted = decryptAndDecompress(data.chat_history);
          if (decrypted) { messages = decrypted.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })); }
      }
      return {
        profile: { id: data.id, contact: data.contact, name: data.name, gender: data.gender, birthDate: data.birth_date, birth_time: data.birth_time, birth_place: data.birth_place, isPremium: data.is_premium, dailyQuestionsLeft: data.daily_questions_left, subscriptionExpiry: data.subscription_expiry ? new Date(data.subscription_expiry) : undefined },
        chatHistory: messages
      };
  } catch (e) { return { profile: null, chatHistory: [] }; }
};

export const generateUniqueUsername = async (fullName: string): Promise<string> => {
    if (!supabase) return fullName.split(' ')[0];
    const firstName = fullName.trim().split(' ')[0];
    try {
        const { data } = await supabase.from('profiles').select('name').ilike('name', `%${firstName}`);
        if (!data || data.length === 0) return firstName;
        const matches = data.filter(p => p.name.toLowerCase() === firstName.toLowerCase() || p.name.toLowerCase().endsWith(` ${firstName.toLowerCase()}`));
        if (matches.length === 0) return firstName;
        return `+${matches.length.toString().padStart(2, '0')} ${firstName}`;
    } catch (e) { return firstName; }
};

export const saveUserProfile = async (user: UserState, messages?: Message[]) => {
  if (!supabase || !user.contact) return; 
  try {
      const payload: any = { contact: user.contact, name: user.name || '', gender: user.gender || '', birth_date: user.birthDate || '', birth_time: user.birthTime || '', birth_place: user.birthPlace || '', is_premium: !!user.isPremium, daily_questions_left: typeof user.dailyQuestionsLeft === 'number' ? user.dailyQuestionsLeft : 0, subscription_expiry: user.subscriptionExpiry ? user.subscriptionExpiry.toISOString() : null };
      if (messages && messages.length > 0) payload.chat_history = compressAndEncrypt(messages);
      await supabase.from('profiles').upsert(payload, { onConflict: 'contact' });
  } catch (e) {}
};

export const fetchCommunicationLogs = async (): Promise<CommunicationLog[]> => {
    if (!supabase) return [];
    try {
        const { data, error } = await supabase.from('communications').select('*').order('timestamp', { ascending: false });
        if (error || !data) return [];
        return data.map((log: any) => ({ id: log.id, type: log.type, recipient: log.recipient, direction: log.direction, status: log.status, timestamp: log.timestamp, details: log.details }));
    } catch (e) { return []; }
};

import React, { useState } from 'react';
import StarBackground from './StarBackground';
import { sendAuthOtp, verifyAuthOtp } from '../../services/dbService';

interface LandingPageProps {
  onSeekerEnter: () => void;
  onSeekerLogin: (verifiedContact: string) => void;
  onVerifyCredentials: (contact: string, password: string) => Promise<boolean>;
  onGuruEnter: () => void;
  onAdminEnter: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onSeekerEnter, onSeekerLogin, onGuruEnter, onAdminEnter }) => {
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginStep, setLoginStep] = useState<'contact' | 'otp'>('contact');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [otp, setOtp] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [adminPin, setAdminPin] = useState('');

  const handleContactSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg('');

    if (isAdminMode) {
        if (adminPin === '1609') onAdminEnter();
        else setErrorMsg("Incorrect Admin PIN");
        return;
    }

    if (phoneNumber.toLowerCase().trim() === 'admin') {
        setIsAdminMode(true);
        return;
    }

    if (phoneNumber.length < 4) {
        setErrorMsg("Please enter a valid contact.");
        return;
    }

    setIsLoading(true);
    try {
        const result = await sendAuthOtp(phoneNumber);
        if (result.success) {
            setLoginStep('otp');
        } else {
            setErrorMsg(result.message || "Failed to send OTP.");
        }
    } catch (e) {
        setErrorMsg("Connection error.");
    } finally {
        setIsLoading(false);
    }
  };

  const handleOtpSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setErrorMsg('');
      setIsLoading(true);
      try {
          const result = await verifyAuthOtp(phoneNumber, otp);
          if (result.success) {
              onSeekerLogin(phoneNumber);
          } else {
              setErrorMsg(result.message || "Invalid OTP Code.");
          }
      } catch (e) {
          setErrorMsg("Verification failed.");
      } finally {
          setIsLoading(false);
      }
  };

  const closeLogin = () => {
      setShowLoginModal(false);
      setIsAdminMode(false);
      setPhoneNumber('');
      setAdminPin('');
      setOtp('');
      setLoginStep('contact');
      setErrorMsg('');
  };

  return (
    <div className="relative min-h-screen flex flex-col items-center justify-center overflow-hidden bg-mystic-900 text-white font-sans selection:bg-gold-500/30">
      <StarBackground />
      <div className="relative z-10 w-full max-w-4xl px-6 flex flex-col items-center text-center animate-in fade-in zoom-in-95 duration-700">
        <div className="mb-12 relative group cursor-default">
