import { GoogleGenAI, Chat } from "@google/genai";
import { BASE_SYSTEM_INSTRUCTION } from '../constants';

let ai: GoogleGenAI | null = null;
let chatSession: Chat | null = null;
let currentInstruction: string = BASE_SYSTEM_INSTRUCTION;

// Usage Tracking
export const apiUsage = {
    totalRequests: 0,
    estimatedTokens: 0,
    lastReset: new Date().toISOString()
};

const trackUsage = (prompt: string, response: string) => {
    apiUsage.totalRequests += 1;
    const tokenMultiplier = prompt.match(/[\u0900-\u097F]/) ? 2 : 1; 
    apiUsage.estimatedTokens += Math.ceil(((prompt.length + response.length) / 4) * tokenMultiplier);
};

const getAI = () => {
  if (!ai) {
    if (!process.env.API_KEY) {
      console.error("API_KEY is missing from environment variables");
      throw new Error("API Key missing");
    }
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return ai;
};

export const initializeChat = async (customInstruction?: string): Promise<Chat> => {
  const client = getAI();

  if (customInstruction) {
    currentInstruction = customInstruction;
  }

  chatSession = client.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: currentInstruction,
      temperature: 0.7,
      maxOutputTokens: 3000, // Sufficient for high-quality premium responses
    }
  });
  return chatSession;
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const sendMessageToGemini = async (message: string, isPremium: boolean = false): Promise<string> => {
  if (!chatSession) {
    await initializeChat();
  }
  if (!chatSession) {
    throw new Error("Failed to initialize chat session");
  }

  const maxRetries = 3;
  let attempt = 0;

  // Differentiated constraints: Premium users get expansive, high-quality answers.
  // Free users get a concise gist to save credits.
  const enhancedMessage = isPremium 
    ? `${message} (PROVIDE EXPANSIVE, HIGH-QUALITY VEDIC ANALYSIS WITH MAXIMUM DETAIL)` 
    : `${message} (BE EXTREMELY CONCISE & PROVIDE ONLY A GIST)`;

  while (attempt < maxRetries) {
    try {
      const result = await chatSession.sendMessage({
        message: enhancedMessage
      });
      const responseText = result.text || "The stars are clouded...";
      trackUsage(enhancedMessage, responseText);
      return responseText;
    } catch (error: any) {
      const isQuotaError = error?.status === 429 || error?.code === 429 || error?.message?.includes('quota');
      if (isQuotaError) {
        attempt++;
        if (attempt < maxRetries) {
            await delay(Math.pow(2, attempt) * 1000);
            continue;
        }
      }
      return "A cosmic interference disrupted my connection. Please try again.";
    }
  }
  return "Connection failed.";
};

export const generateJsonContent = async (prompt: string, maxTokens: number = 1000): Promise<any> => {
    const client = getAI();
    try {
        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                maxOutputTokens: maxTokens
            }
        });

        const text = response.text;
        if (!text) return null;
        trackUsage(prompt, text);
        return JSON.parse(text);
    } catch (e) {
        console.error("JSON Generation Error:", e);
        return null;
    }
};

import { supabase } from './supabaseClient';
import { Product, Transaction, UserState, Message, Astrologer, CommunicationLog } from '../types';
import { MOCK_PRODUCTS, MOCK_ASTROLOGERS } from '../constants';
import { compressAndEncrypt, decryptAndDecompress } from './securityService';

// --- HELPERS ---
export const generateReferenceId = (type: 'Product' | 'Subscription' | 'Dakshina' | 'Consultation' | 'Log', subtype?: string) => {
    const random = Math.floor(1000 + Math.random() * 9000);
    let prefix = 'GEN';
    switch(type) {
        case 'Product': prefix = 'STR'; break;
        case 'Consultation': prefix = 'CNS'; break;
        case 'Subscription': prefix = 'SUB'; break;
        case 'Dakshina': prefix = 'TIP'; break;
        case 'Log': prefix = 'LOG'; break;
    }
    if (subtype && type === 'Subscription') {
        let tierCode = 'GEN';
        const lowerSub = subtype.toLowerCase();
        if (lowerSub.includes('monthly')) tierCode = 'MTH';
        else if (lowerSub.includes('yearly')) tierCode = 'YR';
        return `${prefix}-${tierCode}-${random}`;
    }
    return `${prefix}-${random}`;
};

// --- LOGGING ---
export const logCommunication = async (
    type: CommunicationLog['type'],
    recipient: string,
    direction: CommunicationLog['direction'],
    status: CommunicationLog['status'],
    details?: string
) => {
    const logId = generateReferenceId('Log');
    if (supabase) {
        try {
            await supabase.from('communications').insert([{
                id: logId,
                type,
                recipient,
                direction,
                status,
                details,
                timestamp: new Date().toISOString()
            }]);
        } catch (e) {}
    }
};

// --- RATE LIMITING LOGIC ---
const checkOtpRateLimit = async (contact: string): Promise<{ allowed: boolean; message?: string }> => {
    if (!supabase) return { allowed: true };
    const oneHourAgo = new Date(Date.now() - 3600000).toISOString();

    // 1. Check user-specific limit (1 per hour)
    const { count: userCount } = await supabase
        .from('communications')
        .select('*', { count: 'exact', head: true })
        .eq('recipient', contact)
        .eq('status', 'sent')
        .in('type', ['email', 'sms'])
        .gte('timestamp', oneHourAgo);

    if (userCount !== null && userCount >= 1) {
        return { allowed: false, message: "Limit: 1 verification code per hour for this number/email." };
    }

    // 2. Check global limit (15 per hour)
    const { count: globalCount } = await supabase
        .from('communications')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'sent')
        .in('type', ['email', 'sms'])
        .gte('timestamp', oneHourAgo);

    if (globalCount !== null && globalCount >= 15) {
        return { allowed: false, message: "System Busy: Cosmic traffic is high. Try again in 15 minutes." };
    }

    return { allowed: true };
};

// --- AUTHENTICATION (OTP-ONLY) ---
export const sendAuthOtp = async (contact: string): Promise<{ success: boolean; message?: string; isRateLimit?: boolean }> => {
    if (!supabase) return { success: false, message: "System not initialized" };

    const limitCheck = await checkOtpRateLimit(contact);
    if (!limitCheck.allowed) {
        return { success: false, message: limitCheck.message, isRateLimit: true };
    }

    const isEmail = /[a-zA-Z@]/.test(contact);
    try {
        let error;
        if (isEmail) {
            const res = await supabase.auth.signInWithOtp({
                email: contact,
                options: { shouldCreateUser: true }
            });
            error = res.error;
        } else {
            const phone = contact.replace(/[\s-]/g, '');
            const res = await supabase.auth.signInWithOtp({
                phone: phone,
                options: { shouldCreateUser: true }
            });
            error = res.error;
        }

        if (error) {
            await logCommunication(isEmail ? 'email' : 'sms', contact, 'outbound', 'failed', error.message);
            return { success: false, message: error.message };
        }

        await logCommunication(isEmail ? 'email' : 'sms', contact, 'outbound', 'sent', 'OTP Sent');
        return { success: true };
    } catch (e: any) {
        return { success: false, message: e.message };
    }
};

export const verifyAuthOtp = async (contact: string, token: string): Promise<{ success: boolean; message?: string }> => {
    if (!supabase) return { success: false, message: "System not initialized" };
    const isEmail = /[a-zA-Z@]/.test(contact);
    try {
        let error, data;
        if (isEmail) {
            ({ data, error } = await supabase.auth.verifyOtp({ email: contact, token, type: 'email' }));
        } else {
            const phone = contact.replace(/[\s-]/g, '');
            ({ data, error } = await supabase.auth.verifyOtp({ phone, token, type: 'sms' }));
        }

        if (error) return { success: false, message: error.message };

        if (data.session) {
            await logCommunication(isEmail ? 'email' : 'sms', contact, 'inbound', 'completed', 'OTP Verified');
            return { success: true };
        }
        return { success: false, message: "Incorrect or expired code." };
    } catch (e: any) {
        return { success: false, message: "Verification failed." };
    }
};

