export const fetchUserProfile = async (contact: string | string[]): Promise<{ profile: any | null, chatHistory: Message[] }> => {
  if (!supabase) return { profile: null, chatHistory: [] };
  try {
      let query = supabase.from('profiles').select('*');
      if (Array.isArray(contact)) { query = query.in('contact', contact); }
      else { query = query.eq('contact', contact); }
      const { data, error } = await query.limit(1).maybeSingle();
      if (error || !data) return { profile: null, chatHistory: [] };
      let messages: Message[] = [];
      if (data.chat_history) {
          const decrypted = decryptAndDecompress(data.chat_history);
          if (decrypted) { messages = decrypted.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })); }
      }
      return {
        profile: { id: data.id, contact: data.contact, name: data.name, gender: data.gender, birthDate: data.birth_date, birthTime: data.birth_time, birthPlace: data.birth_place, isPremium: data.is_premium, dailyQuestionsLeft: data.daily_questions_left, subscriptionExpiry: data.subscription_expiry ? new Date(data.subscription_expiry) : undefined },
        chatHistory: messages
      };
  } catch (e) { return { profile: null, chatHistory: [] }; }
};

export const generateUniqueUsername = async (fullName: string): Promise<string> => {
    if (!supabase) return fullName.split(' ')[0];
    const firstName = fullName.trim().split(' ')[0];
    try {
        const { data } = await supabase.from('profiles').select('name').ilike('name', `%${firstName}`);
        if (!data || data.length === 0) return firstName;
        const matches = data.filter(p => p.name.toLowerCase() === firstName.toLowerCase() || p.name.toLowerCase().endsWith(` ${firstName.toLowerCase()}`));
        if (matches.length === 0) return firstName;
        return `+${matches.length.toString().padStart(2, '0')} ${firstName}`;
    } catch (e) { return firstName; }
};

export const saveUserProfile = async (user: UserState, messages?: Message[]) => {
  if (!supabase || !user.contact) return; 
  try {
      const payload: any = { contact: user.contact, name: user.name || '', gender: user.gender || '', birth_date: user.birthDate || '', birth_time: user.birthTime || '', birth_place: user.birthPlace || '', is_premium: !!user.isPremium, daily_questions_left: typeof user.dailyQuestionsLeft === 'number' ? user.dailyQuestionsLeft : 0, subscription_expiry: user.subscriptionExpiry ? user.subscriptionExpiry.toISOString() : null };
      if (messages && messages.length > 0) payload.chat_history = compressAndEncrypt(messages);
      await supabase.from('profiles').upsert(payload, { onConflict: 'contact' });
  } catch (e) {}
};

export const fetchCommunicationLogs = async (): Promise<CommunicationLog[]> => {
    if (!supabase) return [];
    try {
        const { data, error } = await supabase.from('communications').select('*').order('timestamp', { ascending: false });
