import { GoogleGenAI, Chat } from "@google/genai";
import { BASE_SYSTEM_INSTRUCTION } from '../constants';

let ai: GoogleGenAI | null = null;
let chatSession: Chat | null = null;
let currentInstruction: string = BASE_SYSTEM_INSTRUCTION;

// Usage Tracking
export const apiUsage = {
    totalRequests: 0,
    estimatedTokens: 0,
    lastReset: new Date().toISOString()
};

const trackUsage = (prompt: string, response: string) => {
    apiUsage.totalRequests += 1;
    const tokenMultiplier = prompt.match(/[\u0900-\u097F]/) ? 2 : 1; 
    apiUsage.estimatedTokens += Math.ceil(((prompt.length + response.length) / 4) * tokenMultiplier);
};

const getAI = () => {
  if (!ai) {
    if (!process.env.API_KEY) {
      console.error("API_KEY is missing from environment variables");
      throw new Error("API Key missing");
    }
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return ai;
};

export const initializeChat = async (customInstruction?: string): Promise<Chat> => {
  const client = getAI();

  if (customInstruction) {
    currentInstruction = customInstruction;
  }

  chatSession = client.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: currentInstruction,
      temperature: 0.8,
      maxOutputTokens: 3500, // Ample room for high-fidelity premium content
    }
  });
  return chatSession;
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const sendMessageToGemini = async (message: string, isPremium: boolean = false): Promise<string> => {
  if (!chatSession) {
    await initializeChat();
  }
  if (!chatSession) {
    throw new Error("Celestial session not active.");
  }

  const maxRetries = 3;
  let attempt = 0;

  // PREMIUM QUALITY ASSURANCE:
  // We explicitly instruct the model to provide deep, expansive, and high-quality analysis for paid users.
  // For free users, we keep it limited to a "gist" to incentivize upgrading and manage costs.
  const enhancedMessage = isPremium 
    ? `${message} (TIER: PREMIUM - PROVIDE MAXIMUM DEPTH, EXPANSIVE EXPLANATIONS, AND HIGH-QUALITY ANALYSIS. DO NOT SUMMARIZE.)` 
    : `${message} (TIER: FREE - BE EXTREMELY CONCISE, PROVIDE ONLY A SHORT GIST/SUMMARY TO CONSERVE ENERGY.)`;

  while (attempt < maxRetries) {
    try {
      const result = await chatSession.sendMessage({
        message: enhancedMessage
      });
      const responseText = result.text || "The stars are momentarily obscured...";
      trackUsage(enhancedMessage, responseText);
      return responseText;
    } catch (error: any) {
      const isQuotaError = error?.status === 429 || error?.code === 429 || error?.message?.includes('quota');
      if (isQuotaError) {
        attempt++;
        if (attempt < maxRetries) {
            await delay(Math.pow(2, attempt) * 1000);
            continue;
        }
      }
      return "The connection to the heavens was interrupted. Please attempt your query again.";
    }
  }
  return "Connection to the cosmic matrix failed.";
};

export const generateJsonContent = async (prompt: string, maxTokens: number = 1000): Promise<any> => {
    const client = getAI();
    try {
        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                maxOutputTokens: maxTokens
            }
        });

        const text = response.text;
        if (!text) return null;
        trackUsage(prompt, text);
        return JSON.parse(text);
    } catch (e) {
        console.error("Cosmic JSON Error:", e);
        return null;
    }
};

