    } catch (error) { setMessages(prev => [...prev, { id: generateId(), text: "Connection clouded.", sender: Sender.AI, timestamp: new Date() }]); } 
    finally { setIsAiThinking(false); }
  };

  if (isGlobalLoading) return <FullScreenLoader text={loadingText} />;
  if (!hasStarted) return <LandingPage onSeekerEnter={() => setHasStarted(true)} onSeekerLogin={handleSeekerLogin} onVerifyCredentials={async () => true} onGuruEnter={() => { setHasStarted(true); setUserState(p=>({...p, hasOnboarded:true})); setView(AppView.ASTRO_DASHBOARD); }} onAdminEnter={() => { setHasStarted(true); setView(AppView.ADMIN_DASHBOARD); }} />;
  if (view === AppView.ADMIN_DASHBOARD) return <div className="relative min-h-screen"><StarBackground /><AdminDashboard products={products} transactions={transactions} astrologers={astrologers} onUpdateProducts={setProducts} onLogout={handleLogout} onImpersonate={async (u) => { handleSeekerLogin(u.contact); setView(AppView.CHAT); }} /></div>;

  return (
    <div className="relative min-h-screen font-sans text-mystic-100 flex flex-col bg-mystic-900 overflow-hidden">
      <StarBackground />
      {userState.hasOnboarded && <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} user={userState} onNavigate={(v) => { if(v==='chart') setShowChartModal(true); else setView(v); setIsSidebarOpen(false); }} onOpenProfile={() => { setShowProfileModal(true); setIsSidebarOpen(false); }} onOpenHistory={(t) => { setHistoryTab(t); setShowHistoryModal(true); setIsSidebarOpen(false); }} onLogout={handleLogout} onLanguageChange={handleLanguageChange} />}
      {showHistoryModal && <HistoryModal transactions={transactions} onClose={() => setShowHistoryModal(false)} initialTab={historyTab} />}
      {callState.isActive && <CallInterface partnerName={callState.partnerName} partnerImage={callState.partnerImage} callType={callState.type} onEndCall={(d) => setCallState(p=>({...p, isActive:false}))} channelName={callState.channelName || 'default'} />}

      {userState.hasOnboarded && (
          <header className="fixed top-0 left-0 right-0 z-50 flex items-center justify-between p-4 md:p-6 border-b border-white/5 bg-mystic-900/95 backdrop-blur-2xl transition-all shadow-2xl">
            <div className="flex items-center gap-4">
                <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-gold-400 hover:text-white transition-colors"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg></button>
                <h1 className="text-xl md:text-2xl font-serif font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-mystic-200 truncate">{t.appName}</h1>
            </div>
            <div className="flex items-center gap-3">
                {userState.connectedAstrologerId && <button onClick={disconnectAstrologer} className="bg-red-900/30 text-red-400 px-3 py-1.5 rounded-full text-xs font-bold uppercase">{t.endChat}</button>}
                <div className="hidden md:flex bg-white/5 rounded-full p-1 border border-white/10">
                    {[AppView.CHAT, AppView.HOROSCOPE, AppView.MARKETPLACE, AppView.SHOP].map((v) => (
                        <button key={v} onClick={() => setView(v)} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all ${view === v ? 'bg-mystic-100 text-mystic-900' : 'text-mystic-400 hover:text-white'}`}>{v === AppView.CHAT ? t.chat : v === AppView.MARKETPLACE ? t.gurus : t.shop}</button>
                    ))}
                </div>
            </div>
          </header>
      )}

      <main className={`relative z-10 flex-1 flex flex-col max-w-5xl w-full mx-auto h-screen ${userState.hasOnboarded ? 'pt-20 md:pt-24' : ''}`}>
        {!userState.hasOnboarded ? <UserOnboarding onSubmit={handleOnboardingSubmit} onGuruLogin={() => { setHasStarted(true); setUserState(p=>({...p, hasOnboarded:true})); setView(AppView.ASTRO_DASHBOARD); }} /> : (
            <>
                {view === AppView.ASTRO_DASHBOARD ? <AstrologerDashboard activeUser={userState} messages={messages} onAction={() => {}} earnings={astrologerEarnings} astrologers={astrologers} products={products} /> : view === AppView.CHAT ? (
                    <div className="flex flex-col h-full animate-in fade-in duration-500 relative">
                        <div ref={chatContainerRef} onScroll={() => setShowScrollButton(chatContainerRef.current ? chatContainerRef.current.scrollHeight - chatContainerRef.current.scrollTop - chatContainerRef.current.clientHeight > 100 : false)} className="flex-1 overflow-y-auto scrollbar-hide pr-2 pb-48 pt-4 px-4 md:px-0 scroll-smooth">
                            {messages.map((msg) => <MessageBubble key={msg.id} message={msg} onUnlock={(id)=>setMessages(p=>p.map(m=>m.id===id?{...m,isLocked:false}:m))} onPay={(a)=>initiatePayment(a, 'Divine Gift', ()=>handleSendMessage('Gift Sent!'))} onAcceptCall={()=>{}} onSubscribe={()=>{setShowPremiumModal(true)}} onBuyProduct={initiateProductPurchase} userHasPremium={userState.isPremium} userName={userState.name} language={userState.language || 'en'} astrologers={astrologers} />)}
                            {isAiThinking && <ThinkingBubble />}
                            <div ref={messagesEndRef} />
                        </div>
                        {showScrollButton && <button onClick={scrollToBottom} className="fixed bottom-36 right-6 md:right-[calc(50%-20px)] md:left-auto md:translate-x-full z-40 bg-mystic-800 p-3 rounded-full border border-gold-500/30 shadow-lg text-gold-400 hover:bg-mystic-700 transition-all animate-bounce">↓</button>}
                        <div className="fixed bottom-0 left-0 w-full z-40 pointer-events-none">
                            <div className="max-w-5xl mx-auto relative px-4 pb-6 pt-4 bg-gradient-to-t from-mystic-900 via-mystic-900 to-transparent pointer-events-auto">
                                <div className="relative flex items-center bg-mystic-800/80 backdrop-blur-xl border border-mystic-600/30 rounded-full p-2 shadow-2xl gap-2">
                                    <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()} placeholder={userState.connectedAstrologerId ? "Message Guru..." : t.typeMessage} disabled={isAiThinking} className="flex-1 bg-transparent border-none focus:ring-0 text-white placeholder-mystic-400 px-2 py-2 font-sans text-lg outline-none" />
                                    <button onClick={() => handleSendMessage()} disabled={!input.trim() || isAiThinking} className="w-12 h-12 rounded-full bg-gradient-to-br from-violet-600 to-indigo-600 flex items-center justify-center text-white hover:shadow-lg disabled:opacity-50 transition-all transform hover:scale-105">➤</button>
                                </div>
                            </div>
                        </div>
                    </div>
                ) : view === AppView.MARKETPLACE ? <div className="flex-1 overflow-y-auto scrollbar-hide p-4 md:p-0"><div className="grid grid-cols-1 md:grid-cols-2 gap-4 pb-10">{astrologers.map(astro => (<AstroCard key={astro.id} astrologer={astro} onConnect={connectToAstrologer} connectedAstrologerId={userState.connectedAstrologerId}/>))}</div></div> : <Shop products={products} onBuy={initiateProductPurchase} />}
            </>
        )}
      </main>

      {showPaymentConfirmation && pendingPayment && <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95"><div className="bg-mystic-800 p-8 rounded-3xl text-center max-w-sm w-full border border-gold-500/20"><h3 className="text-2xl font-serif text-white mb-2">Confirm Offering</h3><p className="text-gold-400 font-bold text-3xl mb-8">₹{pendingPayment.amount}</p><div className="flex gap-4"><button onClick={()=>setShowPaymentConfirmation(false)} className="flex-1 bg-white/5 py-4 rounded-2xl text-mystic-400 font-bold uppercase tracking-widest text-xs">Cancel</button><button onClick={proceedToRazorpay} className="flex-1 bg-gold-500 py-4 rounded-2xl text-mystic-900 font-black uppercase tracking-widest text-xs shadow-lg">Proceed Offer</button></div></div></div>}
      {showAddressModal && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md"><div className="bg-mystic-800 p-10 rounded-[2rem] w-full max-w-md border border-white/10 shadow-2xl"><h4 className="text-2xl font-serif text-white mb-6">Sanctuary Address</h4><div className="space-y-4"><input value={shippingDetails.address} onChange={e=>setShippingDetails({...shippingDetails, address:e.target.value})} placeholder="House No / Street" className="w-full bg-mystic-900 border-2 border-mystic-700 rounded-2xl px-6 py-4 text-white focus:border-gold-500 outline-none transition-all"/><input value={shippingDetails.city} onChange={e=>setShippingDetails({...shippingDetails, city:e.target.value})} placeholder="City & Pincode" className="w-full bg-mystic-900 border-2 border-mystic-700 rounded-2xl px-6 py-4 text-white focus:border-gold-500 outline-none transition-all"/><button onClick={confirmPurchaseWithAddress} className="w-full bg-gold-500 text-mystic-900 font-black py-5 rounded-2xl mt-4 uppercase tracking-[0.2em] text-xs">Proceed Offering</button></div></div></div>}
      {showPremiumModal && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl"><div className="bg-mystic-900 p-10 rounded-[3rem] text-center border border-gold-500/30 max-w-sm shadow-2xl"><button onClick={()=>setShowPremiumModal(false)} className="absolute top-6 right-6 text-mystic-500 hover:text-white transition-colors">✕</button><div className="w-20 h-20 bg-gold-500/10 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl border border-gold-500/30">🔓</div><h3 className="text-3xl font-serif text-white mb-2">Ascend Higher</h3><p className="text-gold-400 font-bold mb-8">{premiumModalReason}</p><button onClick={()=>initiatePayment(299, "Monthly Premium", ()=>{setUserState(p=>({...p, isPremium:true, dailyQuestionsLeft:PREMIUM_DAILY_LIMIT})); setShowPremiumModal(false);})} className="w-full bg-gold-500 text-mystic-900 font-black py-5 rounded-2xl mb-3 uppercase tracking-widest text-xs shadow-xl">Subscribe ₹299</button><button onClick={()=>setShowPremiumModal(false)} className="text-mystic-500 font-bold text-xs uppercase tracking-widest py-2">Maybe later</button></div></div>}
    </div>
  );
}

{
  "name": "Astro-21",
  "description": "A mystical AI chatbot offering astrological insights with a freemium model and connection to real human astrologers.",
  "requestFramePermissions": [
    "camera",
    "microphone",
    "geolocation"
  ]
}

import React, { useState, useEffect } from 'react';
import { sendAuthOtp, verifyAuthOtp, fetchUserProfile } from '../../services/dbService.ts';

export interface OnboardingData {
  contact: string;
  name: string;
  gender: string;
  date: string;
  time: string;
  place: string;
}

interface UserOnboardingProps {
  onSubmit: (data: OnboardingData, wantsPremium: boolean) => void;
  onGuruLogin?: () => void;
}

const COUNTRY_CODES = [
    { code: '+91', country: 'IN', label: 'India (+91)' },
    { code: '+1', country: 'US', label: 'USA/Canada (+1)' },
    { code: '+44', country: 'UK', label: 'UK (+44)' },
    { code: '+61', country: 'AU', label: 'Australia (+61)' },
    { code: '+971', country: 'AE', label: 'UAE (+971)' },
];

const UserOnboarding: React.FC<UserOnboardingProps> = ({ onSubmit, onGuruLogin }) => {
  const [step, setStep] = useState(1);
  const [contactInput, setContactInput] = useState('');
  const [countryCode, setCountryCode] = useState('+91');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [isOtpVerified, setIsOtpVerified] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [timer, setTimer] = useState(0);

  const [formData, setFormData] = useState<OnboardingData>({
    contact: '',
    name: '',
    gender: '',
    date: '',
    time: '',
    place: ''
  });

  const isEmailDetected = /[a-zA-Z@]/.test(contactInput);

  useEffect(() => {
    let interval: any;
    if (timer > 0) interval = setInterval(() => setTimer(prev => prev - 1), 1000);
    return () => clearInterval(interval);
  }, [timer]);

  useEffect(() => {
      setErrorMsg('');
      if (isEmailDetected) setFormData(prev => ({ ...prev, contact: contactInput }));
      else setFormData(prev => ({ ...prev, contact: `${countryCode}${contactInput.trim()}` }));
  }, [contactInput, countryCode, isEmailDetected]);

  // Try to pre-fill location if permission granted
  useEffect(() => {
    if (step === 4 && !formData.place) {
        navigator.geolocation.getCurrentPosition(async (pos) => {
            try {
                // Quick reverse geocode mock for UX feel
                setFormData(prev => ({ ...prev, place: "Detecting Location..." }));
                setTimeout(() => {
                    setFormData(prev => ({ ...prev, place: "Current Location" }));
                }, 1000);
            } catch (e) {}
        });
    }
  }, [step]);

  const handleNext = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setStep(prev => prev + 1);
  };

  const handleSendOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');
      const contact = isEmailDetected ? contactInput : `${countryCode}${contactInput.trim()}`;
      try {
        const { profile } = await fetchUserProfile(contact);
        if (profile) {
            setIsLoading(false);
            setErrorMsg("Your soul is already aligned. Please Login instead.");
            return;
        }
        const result = await sendAuthOtp(contact);
        setIsLoading(false);
        if (result.success) { setOtpSent(true); setTimer(60); } 
        else { setErrorMsg(result.message || "Celestial blockage. Try later."); }
      } catch (err) { setIsLoading(false); }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      setErrorMsg('');
      const contact = isEmailDetected ? contactInput : `${countryCode}${contactInput.trim()}`;
      const result = await verifyAuthOtp(contact, otp);
      setIsLoading(false);
      if (result.success) {
          setIsOtpVerified(true);
          handleNext();
      } else { setErrorMsg(result.message || "Invalid sacred code."); }
  };

  const renderStep1 = () => (
    <div className="space-y-8 animate-in fade-in slide-in-from-right-12 duration-700">
        <div className="text-center mb-8">
             <div className="w-20 h-20 bg-gold-500/10 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl border border-gold-500/30 animate-pulse-slow">📱</div>
             <h3 className="text-3xl font-serif text-white mb-2 uppercase tracking-tighter">AUTHENTICATE</h3>
             <p className="text-mystic-300 text-sm leading-relaxed">Secure your identity with a one-time celestial key.</p>
        </div>
        <form onSubmit={otpSent ? handleVerifyOtp : handleSendOtp} className="space-y-6">
            <div className="flex gap-3">
                {!isEmailDetected && !otpSent && (
                    <select value={countryCode} onChange={(e) => setCountryCode(e.target.value)} className="h-full bg-mystic-900/60 border-2 border-mystic-700 rounded-2xl px-3 text-white focus:outline-none focus:border-gold-500 transition-all font-bold">
                        {COUNTRY_CODES.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
                    </select>
                )}
                <input type="text" value={contactInput} onChange={e => setContactInput(e.target.value)} disabled={otpSent || isLoading} className="flex-1 bg-mystic-900/60 border-2 border-mystic-700 rounded-2xl px-6 py-4 text-white focus:outline-none focus:border-gold-500 text-lg placeholder-mystic-500 transition-all" placeholder="Mobile or Email" autoFocus={!otpSent} />
            </div>
            {otpSent && (
                <div className="mt-4 bg-mystic-800/40 p-6 rounded-3xl border border-gold-500/20 animate-in zoom-in-95 duration-300">
                    <p className="text-center text-xs text-mystic-400 mb-4 font-bold uppercase tracking-widest">Enter cosmic verification code</p>
                    <input type="text" value={otp} onChange={(e) => setOtp(e.target.value.trim())} placeholder="• • • • • •" maxLength={6} className="w-full bg-mystic-950/50 border-2 border-mystic-700 focus:border-green-500 rounded-xl py-4 text-center text-3xl tracking-[0.6em] text-white outline-none font-mono font-black" autoFocus />
                    <button type="button" onClick={handleSendOtp} disabled={timer > 0} className="text-[10px] font-black uppercase tracking-[0.2em] text-mystic-500 hover:text-gold-400 mt-4 block mx-auto transition-colors">{timer > 0 ? `Resend in ${timer}s` : 'Resend Code'}</button>
                </div>
            )}
            {errorMsg && <p className="text-red-400 text-xs text-center font-black bg-red-400/10 py-3 rounded-xl border border-red-400/20">{errorMsg}</p>}
            <button type="submit" disabled={isLoading} className="w-full bg-gradient-to-r from-gold-600 to-gold-400 hover:from-gold-500 hover:to-gold-300 text-mystic-900 font-black py-5 rounded-2xl shadow-xl transition-all transform active:scale-95 flex justify-center uppercase tracking-widest text-sm">
                {isLoading ? <div className="w-6 h-6 border-4 border-mystic-900 border-t-transparent rounded-full animate-spin"></div> : (otpSent ? 'Align Profile' : 'Send Sacred Key')}
            </button>
        </form>
    </div>
  );

  const renderStep2 = () => (
    <form onSubmit={handleNext} className="space-y-8 animate-in fade-in slide-in-from-right-12 duration-700">
        <div className="text-center mb-8"><div className="w-20 h-20 bg-mystic-700/30 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl border border-white/10">👤</div><h3 className="text-3xl font-serif text-white uppercase tracking-tighter">WHO ARE YOU?</h3><p className="text-mystic-300 text-sm">Your name carries your vibration.</p></div>
        <div className="space-y-6">
            <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-mystic-900/60 border-2 border-mystic-700 rounded-2xl px-6 py-5 text-white text-xl placeholder-mystic-600 focus:outline-none focus:border-gold-500 transition-all shadow-inner font-bold" placeholder="Full Name" autoFocus />
            <div className="grid grid-cols-3 gap-4">
                {['Male', 'Female', 'Other'].map(g => <button type="button" key={g} onClick={() => setFormData({...formData, gender: g})} className={`py-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all ${formData.gender === g ? 'bg-gold-500 border-gold-500 text-mystic-900 shadow-lg shadow-gold-500/20' : 'bg-mystic-900/30 border-mystic-700 text-mystic-400 hover:border-mystic-500'}`}>{g}</button>)}
            </div>
        </div>
        <button type="submit" disabled={!formData.name || !formData.gender} className="w-full bg-white text-mystic-900 font-black py-5 rounded-2xl shadow-xl uppercase tracking-widest text-sm hover:bg-gold-50 transition-all transform active:scale-95">Next Alignment <span className="ml-2">→</span></button>
    </form>
  );

  const renderStep3 = () => (
    <form onSubmit={handleNext} className="space-y-8 animate-in fade-in slide-in-from-right-12 duration-700">
        <div className="text-center mb-8"><div className="w-20 h-20 bg-mystic-700/30 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl border border-white/10">🕒</div><h3 className="text-3xl font-serif text-white uppercase tracking-tighter text-center">THE SACRED MOMENT</h3><p className="text-mystic-300 text-sm text-center">Exact birth data defines your destiny.</p></div>
        <div className="grid grid-cols-1 gap-6">
            <div className="space-y-2">
                <label className="text-[10px] uppercase font-black tracking-widest text-mystic-400 ml-4">Birth Date</label>
                <input type="date" required value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full bg-mystic-900/60 border-2 border-mystic-700 rounded-2xl px-6 py-5 text-white text-lg [color-scheme:dark] focus:outline-none focus:border-gold-500 transition-all" />
            </div>
            <div className="space-y-2">
                <label className="text-[10px] uppercase font-black tracking-widest text-mystic-400 ml-4">Birth Time</label>
                <input type="time" required value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} className="w-full bg-mystic-900/60 border-2 border-mystic-700 rounded-2xl px-6 py-5 text-white text-lg [color-scheme:dark] focus:outline-none focus:border-gold-500 transition-all" />
            </div>
        </div>
        <button type="submit" disabled={!formData.date || !formData.time} className="w-full bg-white text-mystic-900 font-black py-5 rounded-2xl shadow-xl uppercase tracking-widest text-sm hover:bg-gold-50 transition-all transform active:scale-95">Next Alignment <span className="ml-2">→</span></button>
    </form>
  );

  const renderStep4 = () => (
    <form onSubmit={handleNext} className="space-y-8 animate-in fade-in slide-in-from-right-12 duration-700 flex flex-col items-center">
        {/* Exact Icon Style from Screenshot */}
        <div className="w-20 h-20 bg-mystic-950 rounded-full flex items-center justify-center mb-6 border border-white/5 shadow-[0_0_30px_rgba(59,130,246,0.2)]">
            <div className="text-4xl animate-float">🌍</div>
        </div>

        {/* Exact Typography from Screenshot */}
        <div className="text-center mb-10">
            <h3 className="text-3xl md:text-4xl font-serif text-white uppercase tracking-wider mb-2">BIRTH GEOGRAPHY</h3>
            <p className="text-mystic-300 text-sm font-sans opacity-80">The latitude & longitude of your arrival.</p>
        </div>

        {/* Dynamic Mapping Visual - Response to "where's the map" */}
        <div className="w-full relative group mb-8 h-24 overflow-hidden rounded-2xl border border-white/5 bg-mystic-950 flex items-center justify-center">
            <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/grid.png')]"></div>
            {formData.place ? (
                <div className="relative z-10 text-center animate-in zoom-in-95 duration-500">
                    <div className="text-[10px] text-blue-400 font-mono tracking-[0.3em] uppercase mb-1">Aligning Coordinates</div>
                    <div className="flex gap-2 items-center justify-center">
                        <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-ping"></span>
                        <span className="text-xs font-mono text-mystic-200">POINT: {formData.place.toUpperCase()}</span>
                    </div>
                </div>
            ) : (
                <p className="text-[10px] text-mystic-600 font-mono uppercase tracking-[0.2em]">Input Location to Map</p>
            )}
        </div>

        {/* Input Field Styling from Screenshot */}
        <div className="w-full space-y-2">
             <label className="text-[11px] uppercase font-bold tracking-[0.2em] text-mystic-400 ml-1">PLACE OF ORIGIN</label>
             <div className="relative">
                <input 
                    type="text" 
                    required 
                    value={formData.place} 
                    onChange={e => setFormData({...formData, place: e.target.value})} 
                    className="w-full bg-mystic-950 border border-mystic-800 rounded-3xl px-8 py-6 text-white text-2xl font-serif focus:outline-none focus:border-gold-500 transition-all shadow-2xl placeholder-mystic-800" 
                    placeholder="Allahabad" 
                    autoFocus 
                />
                <div className="absolute right-6 top-1/2 -translate-y-1/2 text-2xl opacity-30">📍</div>
             </div>
        </div>

        {/* Exact Button Style from Screenshot */}
        <button 
            type="submit" 
            disabled={!formData.place} 
            className="w-full mt-6 bg-gold-500 hover:bg-gold-400 disabled:opacity-50 disabled:grayscale text-mystic-900 font-bold py-6 rounded-2xl shadow-[0_10px_40px_rgba(218,165,32,0.3)] uppercase tracking-[0.2em] text-sm transition-all transform active:scale-95 flex items-center justify-center gap-3"
        >
            MAP MY DESTINY <span className="text-lg">→</span>
        </button>
    </form>
  );

  const renderStep5 = () => (
