      setMessages(prev => [...prev, { id: generateId(), text: responseText, sender: Sender.AI, timestamp: new Date(), isLocked: hasDeepDive && !userState.isPremium && !userState.isAdminImpersonating, suggestedProducts: suggestedProducts.length > 0 ? suggestedProducts : undefined }]);
      if (!userState.isAdminImpersonating) setUserState(prev => ({ ...prev, dailyQuestionsLeft: prev.dailyQuestionsLeft - 1 }));
