            <div className="w-24 h-24 mx-auto bg-gradient-to-br from-violet-600 to-indigo-900 rounded-full flex items-center justify-center text-5xl mb-6 shadow-[0_0_30px_rgba(124,58,237,0.5)] border border-white/20">
                🔮
            </div>
            <h1 className="text-5xl md:text-7xl font-serif font-bold bg-clip-text text-transparent bg-gradient-to-r from-white via-gold-200 to-mystic-300 tracking-tighter">
                Astro21
            </h1>
            <p className="mt-4 text-lg md:text-xl text-mystic-300 font-light tracking-widest max-w-xl mx-auto uppercase opacity-60">
                Ancient Vedic Wisdom • Digital Clarity
            </p>
        </div>

        {/* Primary Interaction Area */}
        <div className="w-full max-w-sm space-y-6">
            <button 
                onClick={onSeekerEnter}
                className="w-full bg-gradient-to-r from-gold-600 via-gold-500 to-gold-600 hover:from-gold-500 hover:to-gold-400 text-mystic-900 font-black py-6 rounded-2xl shadow-[0_10px_50px_rgba(218,165,32,0.3)] transition-all transform hover:-translate-y-1 active:scale-95 uppercase tracking-[0.2em] text-sm"
            >
                I am a seeker
            </button>

            <div className="text-sm text-mystic-400 flex flex-col gap-1 items-center">
                <span>Already a member?</span>
                <button 
                    onClick={() => { setIsGuruMode(false); setShowLoginModal(true); }}
                    className="text-gold-400 font-bold hover:text-white transition-colors underline underline-offset-4"
                >
                    Login here
                </button>
            </div>
        </div>
      </div>

      {/* Tertiary / Bottom Action */}
      <div className="mt-auto pb-6 relative z-10 w-full flex justify-center border-t border-white/5 pt-8">
        <button 
            onClick={() => { setIsGuruMode(true); setShowLoginModal(true); }}
            className="text-[10px] text-mystic-600 hover:text-gold-500 transition-colors uppercase tracking-[0.4em] font-black"
        >
            Guru Login
        </button>
      </div>

      {/* Login / Security Modal */}
      {showLoginModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
              <div className="bg-mystic-800 border border-gold-500/30 p-8 rounded-[2.5rem] max-w-sm w-full relative shadow-2xl">
                  <button onClick={closeLogin} className="absolute top-6 right-6 text-mystic-500 hover:text-white p-2">✕</button>

                  {isGuruMode ? (
                      <div className="animate-in zoom-in-95 duration-300">
                          <h3 className="text-2xl font-serif text-white mb-2 uppercase tracking-widest text-center">GURU KEY</h3>
                          <p className="text-mystic-400 text-xs mb-8 text-center">Enter your sacred access code</p>
                           <form onSubmit={handleCredentialsSubmit} className="space-y-6">
                              <input 
                                  type="password"
