                                  className="w-full bg-black/40 border border-mystic-700 rounded-2xl px-4 py-6 text-white focus:outline-none focus:border-gold-500 text-center tracking-[1em] text-2xl font-black"
                                  autoFocus
                              />
                              {errorMsg && <p className="text-red-400 text-xs text-center font-bold">{errorMsg}</p>}
                              <button type="submit" className="w-full bg-gold-500 text-mystic-900 font-black py-5 rounded-2xl uppercase tracking-widest shadow-lg shadow-gold-500/10">Authenticate</button>
                           </form>
                      </div>
                  ) : (
                      <div className="animate-in slide-in-from-bottom-4 duration-300">
                           {loginStep === 'credentials' && (
                              <form onSubmit={handleCredentialsSubmit} className="space-y-4">
                                  <h3 className="text-2xl font-serif text-white mb-6 uppercase tracking-widest text-center">Login</h3>
                                  <input 
                                      type="text"
                                      value={phoneNumber}
                                      onChange={(e) => setPhoneNumber(e.target.value)}
                                      placeholder="Phone or Email"
                                      className="w-full bg-black/30 border border-mystic-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-gold-500"
                                      autoFocus
                                  />
                                  <input 
                                      type="password"
                                      value={password}
                                      onChange={(e) => setPassword(e.target.value)}
                                      placeholder="Password"
                                      className="w-full bg-black/30 border border-mystic-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-gold-500"
                                  />
                                  {errorMsg && <p className="text-red-400 text-xs font-bold text-center">{errorMsg}</p>}
                                  <button type="submit" disabled={isLoading} className="w-full bg-gold-500 text-mystic-900 font-black py-4 rounded-xl uppercase tracking-widest">Verify</button>
                              </form>
                           )}
                           {loginStep === 'otp' && (
                              <form onSubmit={handleOtpSubmit} className="space-y-6">
                                  <h3 className="text-2xl font-serif text-white mb-2 uppercase tracking-widest text-center">Identity Check</h3>
                                  <p className="text-mystic-400 text-xs mb-4 text-center">Enter the code sent to {phoneNumber}</p>
                                  <input 
                                      type="text"
                                      value={otp}
                                      onChange={(e) => setOtp(e.target.value)}
                                      placeholder="••••••"
                                      className="w-full bg-black/30 border border-mystic-700 rounded-2xl py-5 text-center text-3xl tracking-[0.5em] text-white font-mono"
                                      maxLength={6}
                                      autoFocus
                                  />
                                  <button type="submit" disabled={otp.length < 6 || isLoading} className="w-full bg-gold-500 text-mystic-900 font-black py-5 rounded-2xl">Access Profile</button>
                              </form>
                           )}
                      </div>
                  )}
              </div>
          </div>
      )}
    </div>
  );
};

